package service

import (
	"context"
	"strconv"
	"strings"

	"github.com/jackc/pgx/v5"

	"github.com/gravadigital/jiku-docs/internal/coreapi"
	"github.com/gravadigital/jiku-docs/internal/markdown"
	"github.com/gravadigital/jiku-docs/internal/protocol"
	"github.com/gravadigital/jiku-docs/internal/store"
)

// Location generated by the server (P-1, section 2): documents.new without folderId places the
// document from its relations, creating the folders that are missing. Changing relations later
// never moves it: the location does not matter to persons, only to the CLI and the sync daemon.
//
//	with a project:          /clientes/<client>/<project>/
//	with a client only:      /clientes/<client>/general/
//	neither:                 /general/
//
// The client of a project comes from core (projects.clientId), else from the first of
// jiku.clients; a project without any client goes to /clientes/sin-cliente/<project>/.

// maxSlug is the length of a generated folder or file name (folder names allow 120).
const maxSlug = 100

// generatedFolder returns the folder for a new document without folderId.
func (s *Service) generatedFolder(ctx context.Context, c *Call, fm markdown.Frontmatter) (string, error) {
	segs, err := s.generatedPath(ctx, fm)
	if err != nil {
		return "", err
	}
	return s.ensureFolderPath(ctx, c, segs)
}

func (s *Service) generatedPath(ctx context.Context, fm markdown.Frontmatter) ([]string, error) {
	projectID, clientID := fm.FirstProject, fm.FirstClient
	if projectID == 0 && clientID == 0 {
		return []string{"general"}, nil
	}
	clientName := func(id int64) (string, error) {
		clients, err := s.Core.Clients(ctx)
		if err != nil {
			return "", err
		}
		for _, cl := range clients {
			if cl.ID == id {
				return slugOr(cl.Name, "cliente-"+strconv.FormatInt(id, 10)), nil
			}
		}
		return "cliente-" + strconv.FormatInt(id, 10), nil
	}
	if projectID == 0 {
		cs, err := clientName(clientID)
		if err != nil {
			return nil, err
		}
		return []string{"clientes", cs, "general"}, nil
	}
	projects, err := s.Core.Projects(ctx)
	if err != nil {
		return nil, err
	}
	var project *coreapi.Project
	for i := range projects {
		if projects[i].ID == projectID {
			project = &projects[i]
		}
	}
	ps := "proyecto-" + strconv.FormatInt(projectID, 10)
	if project != nil {
		ps = slugOr(project.Name, ps)
		if project.ClientID != nil && *project.ClientID > 0 {
			clientID = *project.ClientID
		}
	}
	cs := "sin-cliente"
	if clientID != 0 {
		if cs, err = clientName(clientID); err != nil {
			return nil, err
		}
	}
	return []string{"clientes", cs, ps}, nil
}

func slugOr(name, fallback string) string {
	if sl := markdown.Slug(name, maxSlug); sl != "" {
		return sl
	}
	return fallback
}

// ensureFolderPath walks the segments from the root, creating each missing folder (inheriting,
// as the caller: the server creates them on the caller's behalf, folders.* stays admin-only).
// Concurrent creations of the same folder are absorbed by the unique path.
func (s *Service) ensureFolderPath(ctx context.Context, c *Call, segs []string) (string, error) {
	parentID, parentPath := protocol.RootFolderID, "/"
	for _, seg := range segs {
		p := parentPath + seg + "/"
		id, err := s.folderAt(ctx, c, parentID, seg, p)
		if err != nil {
			return "", err
		}
		parentID, parentPath = id, p
	}
	return parentID, nil
}

func (s *Service) folderAt(ctx context.Context, c *Call, parentID, name, path string) (string, error) {
	for attempt := 0; attempt < 3; attempt++ {
		tree, err := s.Tree(ctx)
		if err != nil {
			return "", err
		}
		if f, ok := tree.ByPath(path); ok {
			return f.ID, nil
		}
		// A folder with the same name in another case is the same folder for the unique index.
		for _, child := range tree.Children[parentID] {
			if f, ok := tree.Get(child); ok && strings.EqualFold(f.Name, name) {
				return f.ID, nil
			}
		}
		id := protocol.NewULID()
		err = store.InTx(ctx, s.DB, func(tx pgx.Tx) error {
			ok, err := lockFolderShared(ctx, tx, parentID)
			if err != nil {
				return err
			}
			if !ok {
				return protocol.E(protocol.CodeFolderNotFound)
			}
			return s.insertFolder(ctx, tx, c, &folderRow{ID: id, ParentID: parentID, Name: name, Path: path, InheritACL: true})
		})
		if store.IsUniqueViolation(err, "") {
			continue // created concurrently: read it again
		}
		if err != nil {
			return "", err
		}
		return id, nil
	}
	return "", protocol.E(protocol.CodeInternalError)
}

// freeFileName is `<slug of the title>.md`, or `-2`, `-3`, ... until it is free in the folder.
func (s *Service) freeFileName(ctx context.Context, folderID, title string) (string, error) {
	base := slugOr(title, "documento")
	rows, err := s.DB.Query(ctx, `SELECT lower(file_name) FROM documents WHERE folder_id = $1 AND deleted_at IS NULL
		AND lower(file_name) LIKE $2 ESCAPE '\'`, folderID, likePrefix(strings.ToLower(base)))
	if err != nil {
		return "", err
	}
	taken := map[string]bool{}
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			rows.Close()
			return "", err
		}
		taken[n] = true
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return "", err
	}
	name := base + ".md"
	for i := 2; taken[strings.ToLower(name)]; i++ {
		name = base + "-" + strconv.Itoa(i) + ".md"
	}
	return name, nil
}
